import { randomBytes } from 'node:crypto';

const TIMESTAMP_BYTES = 6; // 48-bit Unix milliseconds, RFC 9562 §5.7
const UUID_BYTES = 16;

/**
 * UUID v7 (RFC 9562): time-ordered and generated by the application, so the id is known
 * before the insert and index pages fill sequentially.
 */
export function newId(now: number = Date.now()): string {
  const bytes = randomBytes(UUID_BYTES);
  bytes.writeUIntBE(now, 0, TIMESTAMP_BYTES);
  bytes[6] = ((bytes[6] ?? 0) & 0x0f) | 0x70; // version 7
  bytes[8] = ((bytes[8] ?? 0) & 0x3f) | 0x80; // variant 10xx
  const hex = bytes.toString('hex');
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    hex.slice(12, 16),
    hex.slice(16, 20),
    hex.slice(20),
  ].join('-');
}
